Here’s a Python implementation using integer cents and fixed-amount discount codes:

```python
from dataclasses import dataclass


def _nonnegative_int(value: int, name: str) -> None:
    if type(value) is not int or value < 0:
        raise ValueError(f"{name} must be a nonnegative integer")


@dataclass(frozen=True)
class Product:
    name: str
    price_cents: int
    quantity: int

    def __post_init__(self) -> None:
        _nonnegative_int(self.price_cents, "price_cents")
        _nonnegative_int(self.quantity, "quantity")


class Cart:
    def __init__(self, discount_codes: dict[str, int]) -> None:
        # Normalize codes so that, for example, "save10" and "SAVE10"
        # refer to the same discount.
        self._discount_codes: dict[str, int] = {}
        for code, amount_cents in discount_codes.items():
            normalized = self._normalize_code(code)
            _nonnegative_int(amount_cents, "discount amount")
            if normalized in self._discount_codes:
                raise ValueError(f"Duplicate discount code: {normalized}")
            self._discount_codes[normalized] = amount_cents

        self._products: list[Product] = []
        self._applied_codes: set[str] = set()

    @staticmethod
    def _normalize_code(code: str) -> str:
        normalized = code.strip().upper()
        if not normalized:
            raise ValueError("Discount code cannot be empty")
        return normalized

    def add_product(self, product: Product) -> None:
        self._products.append(product)

    def apply_discount(self, code: str) -> None:
        code = self._normalize_code(code)
        if code not in self._discount_codes:
            raise ValueError("Invalid discount code")
        if code in self._applied_codes:
            raise ValueError("Discount code has already been applied")
        self._applied_codes.add(code)

    def final_price_cents(self) -> int:
        subtotal = sum(p.price_cents * p.quantity for p in self._products)
        discount = sum(self._discount_codes[code] for code in self._applied_codes)
        return max(0, subtotal - discount)


cart = Cart({"SAVE10": 1000})  # $10.00 off
cart.add_product(Product("Shirt", price_cents=2500, quantity=2))
cart.apply_discount("save10")

cents = cart.final_price_cents()
print(f"${cents // 100}.{cents % 100:02d}")  # $40.00
```

Applying the same code again raises a `ValueError`, and discounts cannot reduce the total below zero.

